    later versions than the version being described.
    """
    logical_path_map = {}
    for logical_path in inventory.logical_paths:
        content_files = set()
        for file in logical_path.files:
            if file.version == version:
                content_files.add(file.name)
        logical_path_map[logical_path.name] = content_files
    return logical_path_map

