    listed in the manifest are referenced.
    """
    # Validate fixity block structure
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")
    if not fixity.get("fixity_algorithm"):
        raise ValueError("Fixity block must contain a fixity_algorithm key")
    if not fixity.get("digests"):
        raise ValueError("Fixity block must contain a digests key")
    if not isinstance(fixity["digests"], dict):
        raise ValueError("Fixity block must contain a dictionary as the value of the digests key")

