    for file, digest in fixity["digests"].items():
        if file not in manifest_files:
            raise ValueError("File referenced in fixity block is not in the manifest")
        if not isinstance(digest, str) or len(digest) != 64:
            raise ValueError(f"Fixity digest for file {file} must be a 64-character string")

    # Validate fixity algorithm
    fixity_algorithm = fixity["fixity_algorithm"]
    if fixity_algorithm not in ("md5", "sha256"):
        raise ValueError("Fixity algorithm must be either 'md5' or 'sha256'")

    # Validate digests
    for file, digest in fixity["digests"].items():
        if not isinstance(digest, str):
            raise ValueError(f"Fixity digest for file {file} must be a string")
        if fixity_algorithm == "md5" and len(digest) != 32:
            raise ValueError(f"MD5 digest for file {file} must be a 32-character string")
        if fixity_algorithm == "sha256" and len(digest) != 64:
            raise ValueError(f"SHA256 digest for file {file} must be a 64-character string")

