def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    with zipfile.ZipFile(zip_path, 'r') as zip_file:
        file_infos = [ZipInfo(zip_file, info) for info in zip_file.infolist()]
        file_basenames = [os.path.basename(file_info.filename) for file_info in file_infos]
        xml_basenames = [file_basename for file_basename in file_basenames if file_basename.endswith('.xml')]

        files_by_basename = {file_basename: [] for file_basename in xml_basenames}
        for file_info, file_basename in zip(file_infos, file_basenames):
            if file_basename in files_by_basename:
                files_by_basename[file_basename].append(file_info)

        packages_data = {}
        for file_basename, file_infos in files_by_basename.items():
            package_name = file_basename.split('.xml')[0]
            package_data = {'files': []}
            for file_info in file_infos:
                if file_info.filename.endswith('_metadata.xml'):
                    metadata_info = file_info
                elif file_info.filename.endswith('_data.xml'):
                    data_info = file_info
                else:
                    continue
                file_data = zip_file.read(file_info.filename)
                package_data['files'].append(file_data)

            if metadata_info:
                package_data['metadata'] = zip_file.read(metadata_info.filename)
            if data_info:
                package_data['data'] = zip_file.read(data_info.filename)
            packages_data[package_name] = package_data

    return packages_data

