def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    for root_obj_id in self._hierarchy.keys():
        num_objects += 1
        root_obj = self._hierarchy[root_obj_id]
        if check_digests:
            # Check root object digest
            if root_obj.digest != self._compute_digest(root_obj.obj):
                if show_warnings:
                    print(f'Invalid digest for root object {root_obj_id}')
                continue
        if validate_objects:
            # Validate root object
            if not self._validate_obj(root_obj.obj):
                if show_warnings:
                    print(f'Invalid object for root object {root_obj_id}')
                continue
        good_objects += 1
        for child_obj_id in root_obj.children:
            child_obj = self._hierarchy[child_obj_id]
            if check_digests:
                # Check child object digest
                if child_obj.digest != self._compute_digest(child_obj.obj):
                    if show_warnings:
                        print(f'Invalid digest for child object {child_obj_id}')
                    continue
            if validate_objects:
                # Validate child object
                if not self._validate_obj(child_obj.obj):
                    if show_warnings:
                        print(f'Invalid object for child object {child_obj_id}')
                    continue
            good_objects += 1
    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    for object_id, object_dict in self._hierarchy.items():
        num_objects += 1
        parents = object_dict['parents']
        children = object_dict['children']
        if validate_objects:
            for parent in parents:
                if parent not in self._hierarchy:
                    if show_warnings:
