def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    versions = {version_dir: {} for version_dir in version_dirs}
    inventory_versions = set()

    for version_dir, version in versions.items():
        inventory = version.get("inventory")
        if inventory is None:
            raise ValueError(f"No inventory found for version {version_dir}")
        inventory_versions.add(inventory)
        for part in inventory:
            if part not in version:
                raise ValueError(f"Inventory part {part} not found in version {version_dir}")

    if not inventory_versions:
        raise ValueError("No inventories found")

    if len(inventory_versions) != len(versions):
        raise ValueError(f"Inventories are incomplete: {inventory_versions} vs {versions}")

def validate_version_inventories(self, version_dirs):
    """
    Checks that each version directory contains an inventory
    and tracks any content digests different from those in the root inventory.
    """
    # Collect all inventories and content digests
    inventories = {}
    content_digests = {}
    for version_dir in version_dirs:
        # Read the inventory file
        inventory_path = os.path.join(version_dir, "inventory.txt")
        with open(inventory_path, "r") as f:
            inventory = f.read()

        # Parse the inventory into a dict
        inventory_dict = {}
        for line in inventory.splitlines():
            file, _, digest = line.partition(" ")
            inventory_dict[file] = digest

        # Check that all files mentioned in the inventory are present
        for file, digest in inventory_dict.items():
            file_path = os.path.join(version_dir, file)
            if not os.path.isfile(file_path) or not digest == hash_function(file_path):
                raise ValueError(f"Inventory mismatch for {version_dir}")

        # Add the inventory to the list
        inventories[version_dir] = inventory_dict

        # Add any different content digests to the list
        for file, digest in inventory_dict.items():
            if file not in content_digests or digest != content_digests[file]:
                content_digests[file] = digest

    return inventories, content_digests

