    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        # Find the first Namaste file in the directory
        for file in os.listdir(path):
            if file.startswith("0="):
                # Found a Namaste file, parse its contents
                try:
                    namaste = file.split("=", 1)[1]
                    if namaste == "ocfl_1.0":
                        return "root"
                    elif namaste.startswith("ocfl_object_"):
                        return "object"
                    else:
                        return "file"
                except ValueError:
                    return "error: invalid Namaste format"
            return "error: no Namaste file found"
    except OSError:
