def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    # %%%%%%%%%%%%%%%%%%%%%%%%%%%%% Check for file existence %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    if not os.path.exists(path):
        return "Path does not exist"
    elif not os.path.isdir(path):
        return "Path is not a directory"

    # %%%%%%%%%%%%%%%%%%%%%%%%%%%%% Check for Namaste files %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    seen_files = []
    for root, dirs, files in os.walk(path):
        if files:
            seen_files += [f for f in files if f.startswith("0=")]

    if not seen_files:
        return "No Namaste files found"

    # %%%%%%%%%%%%%%%%%%%%%%%%%%%%% Determine directory type %%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
    if any("root" in f for f in seen_files):
        return "root"
    elif any("object" in f for f in seen_files):
        return "object"
    else:
        return "file"

