def vertex_3tuple(vertices: list[Point]) -> list[tuple[Point, Point, Point]]:
    """Return 3 points for each vertex of the polygon.

    Args:
        vertices (list[Point]): The list of vertices of the polygon.

    Returns:
        list[tuple[Point, Point, Point]]: The 3 points for each vertex of the polygon.
    """
    try:
        vertices = [Point(vertex.x, vertex.y) for vertex in vertices]
        result = []
        for i in range(len(vertices)):
            if i < len(vertices) - 1:
                result.append((vertices[i], vertices[i + 1], vertices[(i + 2) % len(vertices)]))
            else:
                result.append((vertices[i], vertices[0], vertices[len(vertices) - 1]))
        return result
    except AttributeError:
        raise ValueError("The input vertices must be a list of Point objects.")

def vertex3tuple(vertices):
    """
    return 3 points for each vertex of the polygon. This will include the vertex and the 2 points on both sides of the vertex::

        polygon with vertices ABCD
        Will return
        DAB, ABC, BCD, CDA -> returns 3tuples
        #A    B    C    D  -> of vertices
    """
    try:
        return [self._vertex3tuple]
    except AttributeError:
        pass
    self._vertex3tuple = []
    for i in range(len(vertices)):
        self._vertex3tuple.append((vertices[i - 1], vertices[i], vertices[(i + 1) % len(vertices)]))
    return self._vertex3tuple

