def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if padding is None:
        padding = len(alphabet) - 1

    base = len(alphabet)
    result = ""

    while number > 0:
        result = alphabet[number % base] + result
        number //= base

    return result.rjust(padding, alphabet[0])

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("alphabet must not be empty")

    if padding is not None and padding < 1:
        raise ValueError("padding must be at least 1")

    if number == 0:
        return alphabet[0]

    is_negative = number < 0
    abs_number = abs(number)
    base = len(alphabet)
    remainder = abs_number % base
    reverse_digits = []

    while abs_number > 0:
        reverse_digits.append(alphabet[remainder])
        abs_number //= base
