def from_ticks(cls, ticks, tz=None):
    if ticks < 0 or ticks >= 86400000000000:
        raise ValueError("ticks must be greater than or equal to 0 and less than 86400000000000")
    if tz is not None and not isinstance(tz, datetime.tzinfo):
        raise TypeError("tz must be None or an instance of datetime.tzinfo")
    if ticks == 0 and tz is None:
        return Time(0, 0, 0, 0)
    hours = ticks // (1000 * 1000)
    minutes = (ticks - hours * (1000 * 1000)) // (1000 * 60)
    seconds = (ticks - hours * (1000 * 1000) - minutes * (1000 * 60)) // 1000
    milliseconds = ticks - hours * (1000 * 1000) - minutes * (1000 * 60) - seconds * 1000
    return Time(hours, minutes, seconds, milliseconds, tz=tz)

