        The resulting graph.
    """
    if not hist.is_numeric():
        raise ValueError("Histogram must contain only numeric bins")
    if make_value is None:
        make_value = lambda bin_: bin_.value
    if get_coordinate == "left":
        get_coordinate = hist.get_bin_left_coordinate
    elif get_coordinate == "right":
        get_coordinate = hist.get_bin_right_coordinate
    elif get_coordinate == "middle":
        get_coordinate = hist.get_bin_middle_coordinate
    else:
        raise ValueError("Invalid get_coordinate:", get_coordinate)
    if field_names is None:
        field_names = ("x", "y")
    if scale is None:
        scale = hist.get_scale()
    result = Graph(dim=len(field_names))
    for i, field_name in enumerate(field_names):
        result.add_axis(field_name)
    for i, bin_ in enumerate(hist.get_bins()):
