    if not cert_file:
        raise SAMLError("Certificate not found")

    if not signature:
        raise SAMLError("Signature not found")

    try:
        signer = self.sec.sec_backend.get_signer(signatureAlgorithm)
    except BadKeyError:
        raise SAMLError("Signature Algoritm not supported")

    if not signer:
        raise SAMLError("Signature not valid")

    if not signer.validate_signature(doc, cert_file):
        raise SAMLError("Signature not valid")

    return True

