def verify(public_key, doc, signature : terms.SignatureType,
           transform_set = None, uri_resolver: Optional[UriResolver] = None,
           signature_algorithm: Optional[str] = None,
           experimental_mappings : bool = False)  -> Tuple[bool, DictType]:

        # Determine the signature algorithm used
        if signature_algorithm is None:
            if signature.signature_algorithm:
                signature_algorithm = signature.signature_algorithm
            else:
                # Determine the signature algorithm used
                signature_algorithm = get_semantic_signature_algorithm(      
                    doc, public_key)

        # Perform necessary transformations
        if signature.reference_uri:
            doc_copy = doc.copy()
            transform_node(doc_copy, signature.reference_uri, transform_set)
            doc = doc_copy

        # Verify the key used to sign the document
        if signature.key_name:
            verify_signed_element(public_key, doc, signature.key_name,
                                 signature_algorithm, signature.digest_method)
        else:
            verify_signed_element(public_key, doc, None,
                                 signature_algorithm, signature.digest_method)

        # Verify the signature itself
        verified = False
        if uri_resolver:
            trusted_x509_certs = set()
            uri_resolver.resolve(doc, trusted_x509_certs)
            if trusted_x509_certs:
                verified = verify_signed_element(public_key, doc, 
                        signature.key_name, signature_algorithm, signature.digest_method)
        else:
            raise ValueError("URI resolver not provided")


        return verified, {"verified": verified}

