def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    try:
        ini_type = IniType(settings_dirs, spec_option)
        return ini_type.list_of_file_names()
    except OSError:
        return []

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    # Loop through each directory in settings_dirs
    for directory in settings_dirs:
        # Loop through each file in the directory
        for file in os.listdir(directory):
            # Check if the file name matches the spec_option
            if file.endswith(spec_option):
                # If it does, add the file name to the list
                yield file

def list_of_file_names(settings_dirs, spec_option):
