def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    try:
        data = yaml.load(open(yaml_file, 'r'), Loader=Loader)
    except FileNotFoundError:
        raise IRValidatorException(f'{yaml_file} does not exist')
    except Exception as e:
        raise IRValidatorException(f'{yaml_file} cannot be loaded: {e}')

    # Validate mandatory fields
    for field in ['type', 'scope', 'owner', 'title', 'version', 'usepackage', 'mandatory']:
        if not data.get(field):
            raise IRValidatorException(f'Missing "{field}" in {yaml_file}')

    # Validate format of fields
    for field, format in cls.VALID_FIELDS:
        if field in data and not re.match(format, data[field]):
            raise IRValidatorException(f'Invalid value for "{field}" in {yaml_file}')

    # Validate semver version
    semver_format = r'^(?P<major>\d+)\.(?P<minor>\d+)\.(?P<patch>\d+)$'
    if 'version' in data and not re.match(semver_format, data['version']):
        raise IRValidatorException(f'Invalid semver version {data["version"]} in {yaml_file}')

    return data

def validate_from_file(cls, yaml_file=None):
    """
    Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """

    if yaml_file is None:
        raise IRValidatorException("Missing required parameter: yaml_file")

    if not yaml_file.exists():
        raise IRValidatorException(f"File not found at '{yaml_file}'")

    with yaml_file.open() as f:
        data = yaml.safe_load(f)

    if data is None:
        raise IRValidatorException(f"Failed to load data from '{yaml_file}'")

    required_fields = [
        "name",
        "description",
        "djd"
    ]

    for field in required_fields:
        if field not in data:
            raise IRValidatorException(f"Mandatory field '{field}' is missing in file '{yaml_file}'")

    if "djd" in data:
        if data["djd"].lower() not in ["true", "false"]:
            raise IRValidatorException(f"Invalid value '{data['djd']}' for field 'djd' in file '{yaml_file}'. Must be 'true' or 'false'")

    return data

