def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if 'include' not in parser_dict:
        return

    include_dict = parser_dict['include']
    for include_key, include_value in include_dict.items():
        if include_key not in self.groups:
            self.groups[include_key] = {}
        include_group = self.groups[include_key]

        for arg_key, arg_value in include_value.items():
            if arg_key not in include_group:
                include_group[arg_key] = arg_value
            else:
                existing_value = include_group[arg_key]
                if isinstance(existing_value, list):
                    existing_value.extend(arg_value)
                elif isinstance(existing_value, Callable):
                    existing_value = self._call_with_existing_args(existing_value, arg_value)
                else:
                    raise ValueError(f"Cannot include value {arg_value} for key {arg_key} in group {include_key}. The existing value is not a list or callable.")
                include_group[arg_key] = existing_value

    del parser_dict['include']

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    :param parser_dict: The parser dictionary containing the include directive
    :type parser_dict: dict
    :return: The resolved parser dictionary
    :rtype: dict
    """
    parser_dict = deepcopy(parser_dict)
    for key, value in parser_dict.items():
        if isinstance(value, dict) and 'include' in value:
            include_value = value.pop('include')
            if isinstance(include_value, str):
                try:
                    included_dict = self._include_groups(ast.literal_eval(include_value))
                except ValueError:
                    included_dict = {}
                parser_dict[key] = included_dict
            elif isinstance(include_value, dict):
                included_dict = self._include_groups(include_value)
                parser_dict[key] = included_dict
    return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    for name, opts in parser_dict.items():
        if name == 'include':
            included_configs = opts['spec']
            if isinstance(included_configs, six.string_types):
                included_configs = [included_configs]
            for included_config in included_configs:
                included_dict = self._load_config_file(included_config)
                for key, val in included_dict.items():
                    if key not in parser_dict:
                        parser_dict[key] = val

