def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.

    Returns:
        dict: The default configurations as set by the `Spec`.

    Raises:
        errors.InvalidSpecError: The `Spec` does not contain
            valid options.
    """
    try:
        spec = self.spec
    except AttributeError:
        raise errors.InvalidSpecError('Spec is not defined')

    defaults = {}
    for arg in spec.args:
        if not isinstance(arg, _BaseOpt):
            raise errors.InvalidSpecError('Unable to get default for non-Option type')

        # if there is a default set, add it to the defaults dict
        if not isinstance(arg.default, NoDefault):
            defaults[arg.name] = arg.default

        # if we have a dict option, build the defaults for its scheme.
        # if any defaults exist, use them.
        if isinstance(arg, DictOption):
            if arg.scheme:
                b = arg.scheme.build_defaults()
                if b:
                    defaults[arg.name] = b
    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """

    # initialize the defaults dictionary
    defaults = {}

    # try to get the spec and default spec attributes
    try:
        spec = self.spec
        default_spec = self._default_spec
    except AttributeError:
        # if either of the attributes is not found, return an empty dictionary
        return defaults

    # check if the spec and default spec are valid
    if not isinstance(spec, Spec):
        raise errors.InvalidSpecError("The 'spec' attribute must be a Spec object")
    if not isinstance(default_spec, DefaultSpec):
        raise errors.InvalidSpecError("The '_default_spec' attribute must be a DefaultSpec object")

    # get the options from the spec and default spec
    options = spec.options()
    default_options = default_spec.options()

    # loop through the options and add their values to the defaults dictionary
    for opt in options + default_options:
        if opt.value is not None:
            defaults[opt.name] = opt.value

    return defaults

